// ============================== Particle systems ==============================
class FlowParticles {
  constructor({ curve, count, size, color, spread, additive, speed }){
    this.curve = curve;
    this.count = count;
    this.speed = speed || 0.12;
    this.direction = 1;
    this.progress = new Float32Array(count);
    this.offsets = [];
    for(let i=0;i<count;i++){
      this.progress[i] = Math.random();
      this.offsets.push(new THREE.Vector3((Math.random()-0.5),(Math.random()-0.5),(Math.random()-0.5)).multiplyScalar(spread || 0.03));
    }
    const positions = new Float32Array(count*3);
    const colors = new Float32Array(count*3);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({
      size: size || 0.05, vertexColors: true, map: glowTexture,
      transparent: true, depthWrite: false, alphaTest: 0.01,
      blending: additive === false ? THREE.NormalBlending : THREE.AdditiveBlending,
      sizeAttenuation: true, opacity: 0.95,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this._tmpColor = new THREE.Color(color || 0xffffff);
  }
  setCurve(curve){ this.curve = curve; }
  update(dt, colorFn){
    const pos = this.points.geometry.attributes.position;
    const col = this.points.geometry.attributes.color;
    for(let i=0;i<this.count;i++){
      this.progress[i] += dt*this.speed*this.direction;
      if (this.progress[i] > 1) this.progress[i] -= 1;
      if (this.progress[i] < 0) this.progress[i] += 1;
      const p = this.curve.getPointAt(clamp(this.progress[i], 0, 0.9999));
      const off = this.offsets[i];
      pos.setXYZ(i, p.x+off.x, p.y+off.y, p.z+off.z);
      const c = colorFn ? colorFn(this.progress[i], i) : this._tmpColor;
      col.setXYZ(i, c.r, c.g, c.b);
    }
    pos.needsUpdate = true; col.needsUpdate = true;
  }
}

class HeatBurst {
  constructor({ anchor, normal, tangent, count, radius, color }){
    this.anchor = anchor.clone();
    this.normal = normal.clone().normalize();
    this.tangent = tangent ? tangent.clone().normalize() : new THREE.Vector3(this.normal.z, 0, -this.normal.x).normalize();
    this.count = count || 12;
    this.radius = radius || 0.2;
    this.progress = new Float32Array(this.count);
    this.seed = new Float32Array(this.count);
    for(let i=0;i<this.count;i++){ this.progress[i] = Math.random(); this.seed[i] = Math.random()*Math.PI*2; }
    const positions = new Float32Array(this.count*3);
    const colors = new Float32Array(this.count*3);
    const sizes = new Float32Array(this.count);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions,3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors,3));
    const mat = new THREE.PointsMaterial({
      size: 0.075, map: glowTexture, vertexColors: true, transparent: true,
      depthWrite: false, alphaTest: 0.01, blending: THREE.AdditiveBlending, sizeAttenuation: true,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.baseColor = new THREE.Color(color || COLORS.heatGlow);
  }
  update(dt, absorbing, active){
    this.points.visible = active;
    if (!active) return;
    const pos = this.points.geometry.attributes.position;
    const col = this.points.geometry.attributes.color;
    for(let i=0;i<this.count;i++){
      this.progress[i] += dt*0.5;
      if (this.progress[i] > 1) this.progress[i] -= 1;
      const t = this.progress[i];
      const travel = absorbing ? (1-t) : t;
      const dist = travel*this.radius*1.5 + 0.02;
      const wobble = Math.sin(t*Math.PI*2 + this.seed[i]) * this.radius*0.3;
      const p = this.anchor.clone()
        .addScaledVector(this.normal, dist)
        .addScaledVector(this.tangent, wobble);
      pos.setXYZ(i, p.x, p.y, p.z);
      const alpha = Math.sin(clamp(t,0,1)*Math.PI);
      col.setXYZ(i, this.baseColor.r*alpha, this.baseColor.g*alpha, this.baseColor.b*alpha);
    }
    pos.needsUpdate = true; col.needsUpdate = true;
  }
}

