function makeCrossFlowFan(length, radius, color){
  const g = new THREE.Group();
  const cylGeo = new THREE.CylinderGeometry(radius, radius, length, 10, 1, false);
  const mat = new THREE.MeshStandardMaterial({ color, roughness: 0.4, metalness: 0.35, flatShading: true });
  const cyl = new THREE.Mesh(cylGeo, mat);
  cyl.rotation.z = Math.PI/2;
  cyl.castShadow = true;
  g.add(cyl);
  const capMat = new THREE.MeshStandardMaterial({ color: COLORS.unitCasingDark, roughness: 0.5, metalness: 0.3 });
  for(const side of [-1,1]){
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(radius*0.35, radius*0.35, 0.03, 12), capMat);
    cap.rotation.z = Math.PI/2;
    cap.position.x = side*length/2;
    g.add(cap);
  }
  return { group: g, spin: cyl };
}

function makeAxialFan(radius, bladeCount, color){
  const g = new THREE.Group();
  const hubMat = new THREE.MeshStandardMaterial({ color: 0x3a4152, roughness: 0.4, metalness: 0.5 });
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(radius*0.18, radius*0.18, radius*0.22, 14), hubMat);
  g.add(hub);
  const bladeGeo = new THREE.BoxGeometry(radius*0.85, 0.012, radius*0.22);
  bladeGeo.translate(radius*0.48, 0, 0);
  const bladeMat = new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.25, side: THREE.DoubleSide });
  for(let i=0;i<bladeCount;i++){
    const b = new THREE.Mesh(bladeGeo, bladeMat);
    b.rotation.y = (i/bladeCount)*Math.PI*2;
    b.rotation.x = 0.4;
    g.add(b);
  }
  return { group: g, spin: g };
}

