function makeCrossFlowFan(length, radius, color){
  // Inner spins around its own local Y (the cylinder's natural axis); the outer
  // wrapper carries whatever static orientation the caller needs. Keeping the
  // spin and the static orientation on separate objects avoids Euler-angle
  // composition artifacts when both change on the same object.
  const inner = new THREE.Group();
  const cylGeo = new THREE.CylinderGeometry(radius, radius, length, 10, 1, false);
  const mat = new THREE.MeshStandardMaterial({ color, roughness: 0.4, metalness: 0.35, flatShading: true });
  const cyl = new THREE.Mesh(cylGeo, mat);
  cyl.castShadow = true;
  inner.add(cyl);
