// ============================== Split system ==============================
const splitGroup = new THREE.Group();
scene.add(splitGroup);
const splitRefs = {};

function buildSplitIndoorUnit(){
  const a = ANCHORS.split.indoorUnit;
  const g = new THREE.Group();
  g.position.copy(a);
  const w = 1.02, h = 0.30, d = 0.24;
  const casingMat = makeCasingMaterial(COLORS.unitCasing);
  const back = new THREE.Mesh(new THREE.BoxGeometry(0.03, h, w), casingMat);
  back.position.set(d/2-0.015, 0, 0); back.castShadow = true; back.receiveShadow = true; g.add(back);
  const top = new THREE.Mesh(new THREE.BoxGeometry(d, 0.025, w), casingMat);
  top.position.set(0, h/2-0.0125, 0); top.castShadow = true; g.add(top);
  const bottom = new THREE.Mesh(new THREE.BoxGeometry(d, 0.025, w), casingMat);
  bottom.position.set(0, -h/2+0.0125, 0); bottom.castShadow = true; g.add(bottom);
  const sideMat = casingMat;
  for(const s of [-1,1]){
    const side = new THREE.Mesh(new THREE.BoxGeometry(d, h, 0.02), sideMat);
    side.position.set(0, 0, s*(w/2-0.01));
    g.add(side);
  }

  const coil = makeFinnedPanel(w*0.88, h*0.62, 12, 3);
  coil.group.rotation.y = Math.PI/2;
  coil.group.position.set(-0.02, 0.01, 0);
  g.add(coil.group);

  const fan = makeCrossFlowFan(w*0.86, 0.055, 0x3a4152);
  fan.group.position.set(-0.06, -0.05, 0);
  g.add(fan.group);

  const louvers = makeLouvers(w*0.82, 7, 0xd7dbe4);
  louvers.rotation.y = Math.PI/2;
  louvers.position.set(-d/2+0.01, -h/2+0.03, 0);
  g.add(louvers);

  const led = new THREE.Mesh(new THREE.BoxGeometry(0.05,0.008,0.008), new THREE.MeshStandardMaterial({ color: 0x6bd4ff, emissive: 0x2fa0ff, emissiveIntensity: 1.2 }));
  led.position.set(-d/2+0.005, h/2-0.03, w/2-0.08);
  g.add(led);

  splitGroup.add(g);
  return { group: g, coil, fan, worldAnchor: a };
}

function buildSplitOutdoorUnit(){
  const a = ANCHORS.split.outdoorUnit;
  const g = new THREE.Group();
  g.position.copy(a);
  const w = 0.82, h = 0.92, d = 0.66;
  const casingMat = makeCasingMaterial(COLORS.unitCasingDark);
  const back = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.03), casingMat);
  back.position.set(0,0,-d/2+0.015); back.castShadow = true; back.receiveShadow = true; g.add(back);
  const bottom = new THREE.Mesh(new THREE.BoxGeometry(w, 0.03, d), casingMat);
  bottom.position.set(0,-h/2+0.015,0); bottom.receiveShadow = true; g.add(bottom);
  for(const s of [-1,1]){
    const side = new THREE.Mesh(new THREE.BoxGeometry(0.025, h, d), casingMat);
    side.position.set(s*(w/2-0.0125), 0, 0);
    side.castShadow = true;
    g.add(side);
  }
  const topRim = new THREE.Mesh(new THREE.BoxGeometry(w, 0.02, d), casingMat);
  topRim.position.set(0, h/2-0.01, 0);
  g.add(topRim);

  const grille = ductGrille(new THREE.Vector3(0, h/2, 0), new THREE.Vector3(0,1,0), w*0.42, 0x8a93a6);
  g.add(grille);

  const fan = makeAxialFan(w*0.38, 5, 0x8a93a6);
  fan.group.position.set(0, h/2-0.06, 0);
  g.add(fan.group);

  const coil = makeFinnedPanel(w*0.86, h*0.7, 14, 4);
  coil.group.position.set(0, -0.05, -d/2+0.05);
  g.add(coil.group);

  const compressor = makeCompressor(1.0);
  compressor.group.position.set(-0.14, -h/2+0.13, d/2-0.22);
  g.add(compressor.group);

  const valve = makeReversingValve(1.0);
  valve.group.position.set(0.18, 0.1, d/2-0.14);
  g.add(valve.group);

  splitGroup.add(g);
  return { group: g, coil, fan, compressor, valve, worldAnchor: a };
}

const splitIndoor = buildSplitIndoorUnit();
const splitOutdoor = buildSplitOutdoorUnit();

function buildSplitPipes(){
  const iu = ANCHORS.split.indoorUnit;
  const ou = ANCHORS.split.outdoorUnit;
  const wallMidY = 1.55;
  const bundleZ = 0.42;

  const gasPts = [
    new THREE.Vector3(iu.x-0.06, iu.y-0.14, iu.z+0.42),
    new THREE.Vector3(iu.x-0.02, iu.y-0.5, iu.z+0.46),
    new THREE.Vector3(-0.02, wallMidY, bundleZ+0.05),
    new THREE.Vector3(0, wallMidY-0.05, bundleZ),
    new THREE.Vector3(0.18, wallMidY-0.1, bundleZ-0.02),
    new THREE.Vector3(0.55, 0.9, bundleZ-0.1),
    new THREE.Vector3(ou.x-0.28, ou.y+0.18, ou.z+0.28),
    new THREE.Vector3(ou.x-0.05, ou.y+0.22, ou.z+0.28),
  ];
  const liquidPts = gasPts.map(p => p.clone().add(new THREE.Vector3(0,0,-0.045)));
  liquidPts[liquidPts.length-1].set(ou.x-0.05, ou.y+0.12, ou.z+0.28);
  liquidPts[liquidPts.length-2].set(ou.x-0.28, ou.y+0.1, ou.z+0.28);

  const gasMat = new THREE.MeshStandardMaterial({ color: 0x333846, roughness: 0.55, metalness: 0.3 });
  const liquidMat = copperMaterial;

