function buildMonoblockCabinet(){
  // Local axes: X = depth (front, into the room, is -X; back, against the wall, is +X).
  // Z = width along the wall. Y = height. This keeps the open front facing the
  // room the same way the split indoor unit does.
  const a = ANCHORS.monoblock.cabinet;
  const g = new THREE.Group();
  g.position.copy(a);
  const cw = 0.62, h = 1.5, cd = 0.52;
  const casingMat = makeCasingMaterial(COLORS.unitCasingMono);
  const back = new THREE.Mesh(new THREE.BoxGeometry(0.03, h, cw), casingMat);
  back.position.set(cd/2-0.015, 0, 0); back.castShadow = true; back.receiveShadow = true; g.add(back);
  const top = new THREE.Mesh(new THREE.BoxGeometry(cd, 0.03, cw), casingMat);
  top.position.set(0, h/2-0.015, 0); g.add(top);
  const bottom = new THREE.Mesh(new THREE.BoxGeometry(cd, 0.05, cw), casingMat);
  bottom.position.set(0, -h/2+0.025, 0); bottom.receiveShadow = true; g.add(bottom);
  for(const s of [-1,1]){
    const side = new THREE.Mesh(new THREE.BoxGeometry(cd, h, 0.02), casingMat);
    side.position.set(0, 0, s*(cw/2-0.01));
    side.castShadow = true; g.add(side);
  }
  for(const foot of [[-1,-1],[1,-1],[-1,1],[1,1]]){
    const f = new THREE.Mesh(new THREE.CylinderGeometry(0.025,0.025,0.05,10), new THREE.MeshStandardMaterial({ color: 0x22262f, roughness: 0.6 }));
    f.position.set(foot[0]*(cd/2-0.05), -h/2-0.02, foot[1]*(cw/2-0.08));
    g.add(f);
  }

  const indoorCoil = makeFinnedPanel(cw*0.82, h*0.32, 9, 3);
  indoorCoil.group.rotation.y = Math.PI/2;
  indoorCoil.group.position.set(cd*0.22, h*0.29, 0);
  g.add(indoorCoil.group);

  const indoorFan = makeCrossFlowFan(cw*0.8, 0.055, 0x3a4152);
  indoorFan.group.rotation.x = Math.PI/2;
  indoorFan.group.position.set(-cd*0.18, h*0.06, 0);
  g.add(indoorFan.group);

  const outdoorCoil = makeFinnedPanel(cw*0.82, h*0.26, 8, 3);
  outdoorCoil.group.rotation.y = Math.PI/2;
  outdoorCoil.group.position.set(cd*0.22, -h*0.28, 0);
  g.add(outdoorCoil.group);

  const outdoorFan = makeAxialFan(cw*0.3, 5, 0x8a93a6);
  outdoorFan.group.rotation.z = Math.PI/2;
  outdoorFan.group.position.set(cd/2-0.14, -h*0.28, 0);
  g.add(outdoorFan.group);

  const compressor = makeCompressor(0.85);
  compressor.group.position.set(-0.06, -h/2+0.16, 0.08);
  g.add(compressor.group);

  const valve = makeReversingValve(0.85);
  valve.group.position.set(0.15, -h*0.22, -0.18);
  g.add(valve.group);

  const frontRimTop = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.03, cw), casingMat);
  frontRimTop.position.set(-cd/2+0.02, h/2-0.015, 0);
  g.add(frontRimTop);

  const led = new THREE.Mesh(new THREE.BoxGeometry(0.008,0.008,0.04), new THREE.MeshStandardMaterial({ color: 0x6bd4ff, emissive: 0x2fa0ff, emissiveIntensity: 1.2 }));
  led.position.set(-cd/2+0.02, h/2-0.06, 0);
  g.add(led);

  monoGroup.add(g);
  return { group: g, indoorCoil, indoorFan, outdoorCoil, outdoorFan, compressor, valve, worldAnchor: a, cw, cd, h };
}

