  class DripSystem {
    constructor(anchor, count){
      this.anchor = anchor.clone();
      this.count = count || 6;
      this.progress = new Float32Array(this.count);
      this.xoff = new Float32Array(this.count);
      for(let i=0;i<this.count;i++){ this.progress[i] = Math.random(); this.xoff[i] = (Math.random()-0.5)*0.3; }
      const geo = new THREE.SphereGeometry(1, 6, 6);
      const mat = new THREE.MeshPhysicalMaterial({ color: 0xbfe0ff, transparent: true, opacity: 0.85, roughness: 0.1, metalness: 0, transmission: 0.3 });
      this.mesh = new THREE.InstancedMesh(geo, mat, this.count);
      this.mesh.frustumCulled = false;
    }
    update(dt, active){
      this.mesh.visible = active;
      if (!active) return;
      const dummy = new THREE.Object3D();
      for(let i=0;i<this.count;i++){
        this.progress[i] += dt*0.35;
        if (this.progress[i] > 1) this.progress[i] -= 1;
        const t = this.progress[i];
        const y = this.anchor.y - t*0.55;
        const scale = 0.012 + 0.006*Math.sin(t*Math.PI);
        dummy.position.set(this.anchor.x + this.xoff[i], y, this.anchor.z);
        dummy.scale.setScalar(scale);
        dummy.updateMatrix();
        this.mesh.setMatrixAt(i, dummy.matrix);
      }
      this.mesh.instanceMatrix.needsUpdate = true;
    }
  }

</script>
</body>

