input.old_string:
function makeFinnedPanel(width, height, finCount, tubeRows){
  const g = new THREE.Group();
  const backing = new THREE.Mesh(new THREE.BoxGeometry(width, height, 0.03), makeCasingMaterial(COLORS.unitCasingDark));
  backing.castShadow = true; backing.receiveShadow = true;
  g.add(backing);
  const finGeo = new THREE.BoxGeometry(width*0.92, height*0.92, 0.01);
  const finMesh = new THREE.InstancedMesh(finGeo, finMaterial, finCount);
  const dummy = new THREE.Object3D();
  for(let i=0;i<finCount;i++){
    const x = -width/2 + (i+0.5)*(width/finCount);
    dummy.position.set(x, 0, 0.02);
    dummy.updateMatrix();
    finMesh.setMatrixAt(i, dummy.matrix);
  }
  finMesh.instanceMatrix.needsUpdate = true;
  g.add(finMesh);

  const pts = [];
  for(let r=0;r<tubeRows;r++){
    const y = -height/2 + (r+0.5)*(height/tubeRows);
    const dir = r % 2 === 0 ? 1 : -1;
    pts.push(new THREE.Vector3(dir*width*0.46, y, 0.03));
    pts.push(new THREE.Vector3(dir*width*0.46, y, 0.05));
    pts.push(new THREE.Vector3(-dir*width*0.46, y, 0.05));
  }
  const curve = new THREE.CatmullRomCurve3(pts.length > 1 ? pts : [new THREE.Vector3(0,0,0), new THREE.Vector3(0.01,0,0)]);
  const tubeGeo = new THREE.TubeGeometry(curve, Math.max(24, tubeRows*10), Math.max(0.012, width*0.02), 8, false);
  const tubeMesh = new THREE.Mesh(tubeGeo, copperMaterial);
  tubeMesh.castShadow = true;
  g.add(tubeMesh);

  return { group: g, finMesh, tubeMesh, backing };
}

input.new_string:
function makeFinnedPanel(width, height, finCount, tubeRows){
  // Each coil gets its own fin/tube materials (not the shared defaults) so its
  // emissive glow can be animated independently — evaporator vs condenser role
  // differs per coil and flips with mode.
  const g = new THREE.Group();
  const backing = new THREE.Mesh(new THREE.BoxGeometry(width, height, 0.03), makeCasingMaterial(COLORS.unitCasingDark));
  backing.castShadow = true; backing.receiveShadow = true;
  g.add(backing);
  const finMat = new THREE.MeshStandardMaterial({ color: COLORS.finMetal, roughness: 0.4, metalness: 0.55, emissive: 0x000000, emissiveIntensity: 0.6 });
  const finGeo = new THREE.BoxGeometry(width*0.92, height*0.92, 0.01);
  const finMesh = new THREE.InstancedMesh(finGeo, finMat, finCount);
  const dummy = new THREE.Object3D();
  for(let i=0;i<finCount;i++){
    const x = -width/2 + (i+0.5)*(width/finCount);
    dummy.position.set(x, 0, 0.02);
    dummy.updateMatrix();
    finMesh.setMatrixAt(i, dummy.matrix);
  }
  finMesh.instanceMatrix.needsUpdate = true;
  g.add(finMesh);

  const pts = [];
  for(let r=0;r<tubeRows;r++){
    const y = -height/2 + (r+0.5)*(height/tubeRows);
    const dir = r % 2 === 0 ? 1 : -1;
    pts.push(new THREE.Vector3(dir*width*0.46, y, 0.03));
    pts.push(new THREE.Vector3(dir*width*0.46, y, 0.05));
    pts.push(new THREE.Vector3(-dir*width*0.46, y, 0.05));
  }
  const curve = new THREE.CatmullRomCurve3(pts.length > 1 ? pts : [new THREE.Vector3(0,0,0), new THREE.Vector3(0.01,0,0)]);
  const tubeGeo = new THREE.TubeGeometry(curve, Math.max(24, tubeRows*10), Math.max(0.012, width*0.02), 8, false);
  const tubeMat = new THREE.MeshStandardMaterial({ color: COLORS.copper, roughness: 0.35, metalness: 0.7, emissive: 0x000000, emissiveIntensity: 0.8 });
  const tubeMesh = new THREE.Mesh(tubeGeo, tubeMat);
  tubeMesh.castShadow = true;
  g.add(tubeMesh);

  return { group: g, finMesh, finMat, tubeMesh, tubeMat, backing };
}

