  // ============================== Flow curves ==============================
  function closedCurve(points){ return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.45); }

  const splitRoomAirCurve = closedCurve([
    new THREE.Vector3(-0.42, 1.88, 0.05),
    new THREE.Vector3(-1.05, 1.58, 0.2),
    new THREE.Vector3(-2.25, 1.15, -0.55),
    new THREE.Vector3(-3.55, 0.9, 0.35),
    new THREE.Vector3(-3.85, 1.6, 1.15),
    new THREE.Vector3(-2.35, 2.1, 0.95),
    new THREE.Vector3(-0.8, 2.15, 0.35),
    new THREE.Vector3(-0.34, 2.08, 0.05),
  ]);

  const splitOutdoorAirCurve = closedCurve([
    new THREE.Vector3(1.1, 0.5, -0.36),
    new THREE.Vector3(1.15, 0.85, -0.18),
    new THREE.Vector3(1.16, 1.05, 0.05),
    new THREE.Vector3(1.2, 1.35, 0.15),
    new THREE.Vector3(1.55, 1.05, 0.55),
    new THREE.Vector3(1.85, 0.55, 0.5),
    new THREE.Vector3(1.6, 0.35, -0.05),
    new THREE.Vector3(1.35, 0.4, -0.28),
  ]);

  const monoRoomAirCurve = closedCurve([
    new THREE.Vector3(-0.9, 1.15, 0.05),
    new THREE.Vector3(-1.6, 1.35, 0.25),
    new THREE.Vector3(-2.85, 1.4, -0.45),
    new THREE.Vector3(-4.05, 1.1, 0.5),
    new THREE.Vector3(-3.5, 0.6, 1.0),
    new THREE.Vector3(-1.8, 0.7, 0.6),
    new THREE.Vector3(-0.92, 0.85, 0.05),
  ]);

  // ============================== Particle instances ==============================
  const AIR_BASE = new THREE.Color(COLORS.airIndoor);
  const AIR_OUT_BASE = new THREE.Color(COLORS.airOutdoor);
  const AIR_COOL_TINT = new THREE.Color(COLORS.coolGas);
  const AIR_WARM_TINT = new THREE.Color(COLORS.hotGas);
  const GAS_COOL_COLOR = new THREE.Color(COLORS.coolGas);
  const GAS_HOT_COLOR = new THREE.Color(COLORS.hotGas);
  const LIQUID_COLOR = new THREE.Color(COLORS.warmLiquid);
  const scratch1 = new THREE.Color();
  const scratch2 = new THREE.Color();
  const scratch3 = new THREE.Color();
  const scratch4 = new THREE.Color();

  function mixFactor(t){ const m = clamp(1 - t/0.4, 0, 1); return m*m*(3-2*m); }
  function angleForMode(mode){ return mode === 'cooling' ? 0 : Math.PI/2; }

  const roomAirSplit = new FlowParticles({ curve: splitRoomAirCurve, count: 70, size: 0.052, spread: 0.03, speed: 0.11 });
  const outdoorAirSplit = new FlowParticles({ curve: splitOutdoorAirCurve, count: 55, size: 0.05, spread: 0.03, speed: 0.13 });
  const roomAirMono = new FlowParticles({ curve: monoRoomAirCurve, count: 62, size: 0.052, spread: 0.03, speed: 0.11 });
  const outdoorAirManoIn = new FlowParticles({ curve: monoDucts.inTube.curve, count: 30, size: 0.05, spread: 0.05, speed: 0.28 });
  const outdoorAirManoOut = new FlowParticles({ curve: monoDucts.outTube.curve, count: 30, size: 0.05, spread: 0.05, speed: 0.28 });
  outdoorAirManoIn.direction = -1;

  const refrigerantGasSplit = new FlowParticles({ curve: splitPipes.gasTube.curve, count: 46, size: 0.042, spread: 0.014, speed: 0.16 });
  const refrigerantLiquidSplit = new FlowParticles({ curve: splitPipes.liquidTube.curve, count: 34, size: 0.03, spread: 0.008, speed: 0.14 });
  const refrigerantGasMono = new FlowParticles({ curve: monoPipes.gasTube.curve, count: 22, size: 0.028, spread: 0.01, speed: 0.4 });
  const refrigerantLiquidMono = new FlowParticles({ curve: monoPipes.liquidTube.curve, count: 18, size: 0.02, spread: 0.006, speed: 0.36 });

  const heatSplitIndoor = new HeatBurst({ anchor: ANCHORS.split.indoorCoil, normal: new THREE.Vector3(-1,0,0), tangent: new THREE.Vector3(0,1,0), count: 14, radius: 0.22 });
  const heatSplitOutdoor = new HeatBurst({ anchor: ANCHORS.split.outdoorCoil, normal: new THREE.Vector3(0,0,1), tangent: new THREE.Vector3(1,0,0), count: 14, radius: 0.24 });
  const heatMonoIndoor = new HeatBurst({ anchor: ANCHORS.monoblock.indoorCoil, normal: new THREE.Vector3(-1,0,0), tangent: new THREE.Vector3(0,0,1), count: 12, radius: 0.2 });
  const heatMonoOutdoor = new HeatBurst({ anchor: ANCHORS.monoblock.outdoorCoil, normal: new THREE.Vector3(-1,0,0), tangent: new THREE.Vector3(0,0,1), count: 12, radius: 0.2 });

  const dripSplit = new DripSystem(ANCHORS.split.indoorCoil.clone().add(new THREE.Vector3(0,-0.14,0)), 6);
  const dripMono = new DripSystem(ANCHORS.monoblock.indoorCoil.clone().add(new THREE.Vector3(0,-0.16,0)), 6);

  splitGroup.add(roomAirSplit.points, outdoorAirSplit.points, refrigerantGasSplit.points, refrigerantLiquidSplit.points,
    heatSplitIndoor.points, heatSplitOutdoor.points, dripSplit.mesh);
  monoGroup.add(roomAirMono.points, outdoorAirManoIn.points, outdoorAirManoOut.points, refrigerantGasMono.points, refrigerantLiquidMono.points,
    heatMonoIndoor.points, heatMonoOutdoor.points, dripMono.mesh);

  const COOL_ROLE_COLOR = new THREE.Color(COLORS.coolGas);
  const HOT_ROLE_COLOR = new THREE.Color(COLORS.hotGas);
  function roleColorObj(role){ return role === 'evaporator' ? COOL_ROLE_COLOR : HOT_ROLE_COLOR; }

  // ============================== Camera framing / highlight ==============================
  const highlightSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color: 0x7fe8c8, transparent: true, opacity: 0.55, depthWrite: false }));
  highlightSprite.visible = false;
  highlightSprite.renderOrder = 5;
  scene.add(highlightSprite);

  function getFocus(name){
    const split = state.systemType === 'split';
    if (name === 'overview'){
      return split ? DEFAULT_VIEW : { position: new THREE.Vector3(-3.0, 2.35, 3.55), target: ANCHORS.monoblock.cabinet.clone().add(new THREE.Vector3(0,0.3,0)) };
    }
    const A = split ? ANCHORS.split : ANCHORS.monoblock;
    const table = split ? {
      indoorUnit: { position: new THREE.Vector3(-1.7, 2.5, 1.5), target: A.indoorUnit },
      outdoorUnit: { position: new THREE.Vector3(2.7, 1.35, 1.9), target: A.outdoorUnit },
      compressor: { position: new THREE.Vector3(2.15, 0.85, 1.4), target: A.compressor },
      reversingValve: { position: new THREE.Vector3(2.35, 1.3, 1.35), target: A.reversingValve },
      indoorCoil: { position: new THREE.Vector3(-1.35, 2.25, 1.15), target: A.indoorCoil },
      outdoorCoil: { position: new THREE.Vector3(2.35, 0.95, -0.75), target: A.outdoorCoil },
      expansionValve: { position: new THREE.Vector3(-0.85, 2.05, 1.25), target: A.expansionValve },
    } : {
      indoorUnit: { position: new THREE.Vector3(-2.0, 1.75, 1.9), target: A.cabinet },
      outdoorUnit: { position: new THREE.Vector3(-1.95, 1.1, 1.75), target: A.outdoorCoil },
      compressor: { position: new THREE.Vector3(-1.55, 0.85, 1.15), target: A.compressor },
      reversingValve: { position: new THREE.Vector3(-1.5, 0.95, 0.9), target: A.reversingValve },
      indoorCoil: { position: new THREE.Vector3(-1.75, 1.65, 1.4), target: A.indoorCoil },
      outdoorCoil: { position: new THREE.Vector3(-1.75, 0.95, 1.3), target: A.outdoorCoil },
      expansionValve: { position: new THREE.Vector3(-1.6, 1.55, 1.1), target: A.expansionValve },
    };
    return table[name] || (split ? DEFAULT_VIEW : table.indoorUnit);
  }

  function startCameraTween(pos, target){
    camAnim.active = true;
    camAnim.t = 0;
    camAnim.duration = state.reducedMotion ? 0.05 : 1.05;
    camAnim.fromPos.copy(camera.position);
    camAnim.fromTarget.copy(controls.target);
    camAnim.toPos.copy(pos);
    camAnim.toTarget.copy(target);
    controls.enabled = false;
  }

  // ============================== Labels ==============================
  const labelLayer = document.getElementById('labelLayer');
  const leaderSvg = document.getElementById('leaderLines');
  let labelDefs = null;
  let currentLabelEls = [];

  function buildLabelDefs(){
    const s = ANCHORS.split, m = ANCHORS.monoblock;
    return {
      split: [
        { text: 'Indoor Unit', anchor: s.indoorUnit, dx: -95, dy: -66 },
        { text: 'Outdoor Unit', anchor: s.outdoorUnit, dx: 105, dy: -58 },
        { text: 'Indoor Coil', anchor: s.indoorCoil, dx: -135, dy: 4 },
        { text: 'Outdoor Coil', anchor: s.outdoorCoil, dx: 110, dy: 46 },
        { text: 'Compressor', anchor: s.compressor, dx: -40, dy: 92 },
        { text: 'Reversing Valve', anchor: s.reversingValve, dx: 118, dy: 72 },
        { text: 'Expansion Valve', anchor: s.expansionValve, dx: -150, dy: -42 },
        { text: 'Liquid Line', anchor: splitPipes.liquidTube.curve.getPointAt(0.55), dx: 34, dy: -96 },
        { text: 'Suction / Gas Line', anchor: splitPipes.gasTube.curve.getPointAt(0.32), dx: -70, dy: -118 },
      ],
      monoblock: [
        { text: 'Monoblock Cabinet', anchor: m.cabinet.clone().add(new THREE.Vector3(0,0.55,0)), dx: -150, dy: -90 },
        { text: 'Indoor Coil', anchor: m.indoorCoil, dx: -155, dy: 2 },
        { text: 'Outdoor Coil', anchor: m.outdoorCoil, dx: -155, dy: 64 },
        { text: 'Compressor', anchor: m.compressor, dx: -40, dy: 104 },
        { text: 'Reversing Valve', anchor: m.reversingValve, dx: 112, dy: 74 },
        { text: 'Expansion Valve', anchor: m.expansionValve, dx: 118, dy: -32 },
        { text: 'Outdoor Intake Duct', anchor: monoDucts.inTube.curve.getPointAt(0.5), dx: 92, dy: -92 },
        { text: 'Outdoor Exhaust Duct', anchor: monoDucts.outTube.curve.getPointAt(0.5), dx: 92, dy: 108 },
      ],
    };
  }

  function rebuildLabels(){
    labelLayer.innerHTML = '';
    leaderSvg.innerHTML = '';
    currentLabelEls = [];
    const defs = labelDefs[state.systemType];
    for (const d of defs){
      const el = document.createElement('div');
      el.className = 'callout';
      el.innerHTML = '<span class="dot" style="background:#7fe0c0"></span>' + d.text;
      labelLayer.appendChild(el);
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('stroke', 'rgba(255,255,255,0.32)');
      line.setAttribute('stroke-width', '1');
      leaderSvg.appendChild(line);
      currentLabelEls.push({ def: d, el, line });
    }
  }

  function updateLabelVisibility(){
    const show = state.labelsOn;
    labelLayer.style.display = show ? '' : 'none';
    leaderSvg.style.display = show ? '' : 'none';
  }

  const _proj = new THREE.Vector3();
  function updateLabels(){
    if (!state.labelsOn || currentLabelEls.length === 0) return;
    const rect = canvas.getBoundingClientRect();
    for (const item of currentLabelEls){
      _proj.copy(item.def.anchor).project(camera);
      const behind = _proj.z > 1 || _proj.z < -1;
      const sx = (_proj.x*0.5+0.5)*rect.width;
      const sy = (1-(_proj.y*0.5+0.5))*rect.height;
      const lx = clamp(sx + item.def.dx, 46, rect.width-46);
      const ly = clamp(sy + item.def.dy, 26, rect.height-26);
      item.el.style.transform = `translate(${lx}px, ${ly}px)`;
      item.el.classList.toggle('hidden', behind);
      item.line.setAttribute('x1', sx); item.line.setAttribute('y1', sy);
      item.line.setAttribute('x2', lx); item.line.setAttribute('y2', ly);
      item.line.style.opacity = behind ? 0 : 0.4;
    }
  }

  // ============================== Tutorial ==============================
  const TUTORIAL_STEPS = [
    {
      title: 'Room air stays indoors',
      body: () => state.systemType === 'split'
        ? 'The indoor unit pulls air from the room, passes it across a coil, and blows it straight back into the room. This loop of room air never leaves the building.'
        : 'The monoblock cabinet pulls room air across its indoor coil and returns it to the room. This air never mixes with the outdoor air moving through the ducts.',
      focus: 'indoorUnit',
    },
    {
      title: 'Outdoor air stays outdoors',
      body: () => state.systemType === 'split'
        ? 'The outdoor unit separately draws in outside air, passes it across its own coil, and releases it back outside. It never enters the building or meets the room air.'
        : 'Outdoor air is ducted through the wall, across the outdoor coil inside the cabinet, then back outside through a second duct — it never enters the room.',
      focus: 'outdoorUnit',
    },
    {
      title: 'Heat enters the refrigerant',
      body: () => {
        const isIndoor = indoorRole(state.mode) === 'evaporator';
        return `The ${isIndoor ? 'indoor' : 'outdoor'} coil is the evaporator right now: cold refrigerant inside absorbs heat from the air passing over it, so that air leaves cooler than it arrived.`;
      },
      focus: () => indoorRole(state.mode) === 'evaporator' ? 'indoorCoil' : 'outdoorCoil',
    },
    {
      title: 'The compressor raises pressure and temperature',
      body: () => 'The compressor squeezes the low-pressure vapor leaving the evaporator into a hot, high-pressure gas. The electricity the system consumes is spent mostly right here.',
      focus: 'compressor',
    },
    {
      title: 'Heat leaves the refrigerant',
      body: () => {
        const isIndoor = indoorRole(state.mode) === 'condenser';
        return `The ${isIndoor ? 'indoor' : 'outdoor'} coil is the condenser right now: hot high-pressure refrigerant gives up its heat to the air passing over it, then condenses into a warm liquid.`;
      },
      focus: () => indoorRole(state.mode) === 'condenser' ? 'indoorCoil' : 'outdoorCoil',
    },
    {
      title: 'The expansion device resets the refrigerant',
      body: () => 'A small metering device drops the liquid refrigerant’s pressure sharply. That sudden drop cools it far below room and outdoor temperature, ready to absorb heat all over again.',
      focus: 'expansionValve',
    },
    {
      title: 'The reversing valve flips the circuit',
      body: () => 'Try switching Cooling / Heating above: the reversing valve redirects the hot compressor discharge to whichever coil should release heat, swapping which coil evaporates and which condenses.',
      focus: 'reversingValve',
    },
    {
      title: 'Split vs. monoblock',
      body: () => state.systemType === 'split'
        ? 'A split system keeps the compressor and one coil outdoors: only two slim refrigerant lines cross the wall, so the loud, hot machinery stays outside.'
        : 'A monoblock keeps the entire refrigeration circuit — compressor, both coils, the reversing valve — inside one indoor cabinet. Only air crosses the wall, through two ducts, never refrigerant.',
      focus: 'overview',
    },
  ];

  const tutorialEl = document.getElementById('tutorial');
  const tutorialTitleEl = document.getElementById('tutorialTitle');
  const tutorialBodyEl = document.getElementById('tutorialBody');
  const tutorialProgressEl = document.getElementById('tutorialProgress');
  const tutorialFillEl = document.getElementById('tutorialProgressFill');
  const tutorialBackBtn = document.getElementById('tutorialBack');
  const tutorialNextBtn = document.getElementById('tutorialNext');
  const tutorialBtn = document.getElementById('tutorialBtn');

  function renderTutorialStep(animateCamera){
    const step = TUTORIAL_STEPS[state.tutorialStep];
    tutorialTitleEl.textContent = step.title;
    tutorialBodyEl.textContent = typeof step.body === 'function' ? step.body() : step.body;
    tutorialProgressEl.textContent = `Step ${state.tutorialStep+1} of ${TUTORIAL_STEPS.length}`;
    tutorialFillEl.style.width = `${((state.tutorialStep+1)/TUTORIAL_STEPS.length)*100}%`;
    tutorialBackBtn.disabled = state.tutorialStep === 0;
    tutorialNextBtn.textContent = state.tutorialStep === TUTORIAL_STEPS.length-1 ? 'Done' : 'Next';

    const focusName = typeof step.focus === 'function' ? step.focus() : step.focus;
    const focus = getFocus(focusName);
    highlightSprite.visible = true;
    highlightSprite.position.copy(focus.target);
    highlightSprite.scale.set(0.55, 0.55, 1);

    if (animateCamera !== false) startCameraTween(focus.position, focus.target);
  }

  function openTutorial(){
    state.tutorialOpen = true;
    state.tutorialStep = 0;
    tutorialEl.hidden = false;
    tutorialBtn.classList.remove('attention');
    renderTutorialStep();
  }
  function closeTutorial(){
    state.tutorialOpen = false;
    tutorialEl.hidden = true;
    highlightSprite.visible = false;
  }
  function tutorialNext(){
    if (state.tutorialStep >= TUTORIAL_STEPS.length-1){ closeTutorial(); return; }
    state.tutorialStep++;
    renderTutorialStep();
  }
  function tutorialBack(){
    if (state.tutorialStep === 0) return;
    state.tutorialStep--;
    renderTutorialStep();
  }

  // ============================== UI wiring ==============================
  function setActiveSeg(group, value){
    group.querySelectorAll('.seg-btn').forEach(btn => {
      const active = btn.dataset.value === value;
      btn.classList.toggle('active', active);
      btn.setAttribute('aria-checked', active ? 'true' : 'false');
    });
  }

  function updateStateText(){
    const sys = state.systemType === 'split' ? 'Split System' : 'Monoblock';
    const modeLabel = state.mode === 'cooling' ? 'Cooling' : 'Heating';
    document.getElementById('stateLine').textContent = `${sys} · ${modeLabel} · ${state.playing ? 'Compressor running' : 'Paused'}`;
    document.getElementById('flowLine').textContent = state.mode === 'cooling'
      ? 'Heat is absorbed from indoor air and rejected outdoors.'
      : 'Heat is absorbed from outdoor air and released indoors.';
  }

  function flashSwap(){
    canvas.style.transition = 'opacity .16s ease';
    canvas.style.opacity = '0.3';
    setTimeout(() => { canvas.style.opacity = '1'; }, 150);
  }

  function setSystemType(value){
    if (value === state.systemType) return;
    state.systemType = value;
    setActiveSeg(systemTypeGroup, value);
    flashSwap();
    splitGroup.visible = value === 'split';
    monoGroup.visible = value === 'monoblock';
    rebuildLabels();
    const focus = getFocus('overview');
    startCameraTween(focus.position, focus.target);
    if (state.tutorialOpen) renderTutorialStep(false);
    updateStateText();
  }

  function setMode(value){
    if (value === state.mode) return;
    modeAnim.from = state.mode;
    modeAnim.to = value;
    modeAnim.t = 0;
    state.mode = value;
    setActiveSeg(modeGroup, value);
    const targets = value === 'cooling' ? { indoor: 22, outdoor: 32 } : { indoor: 21, outdoor: 5 };
    state.indoorTarget = targets.indoor;
    state.outdoorTarget = targets.outdoor;
    updateStateText();
    if (state.tutorialOpen) renderTutorialStep(false);
  }

  const systemTypeGroup = document.getElementById('systemTypeGroup');
  const modeGroup = document.getElementById('modeGroup');
  systemTypeGroup.addEventListener('click', (e) => {
    const btn = e.target.closest('.seg-btn');
    if (btn) setSystemType(btn.dataset.value);
  });
  modeGroup.addEventListener('click', (e) => {
    const btn = e.target.closest('.seg-btn');
    if (btn) setMode(btn.dataset.value);
  });

  const playPauseBtn = document.getElementById('playPauseBtn');
  const playIcon = document.getElementById('playIcon');
  const playLabel = document.getElementById('playLabel');
  playPauseBtn.addEventListener('click', () => {
    state.playing = !state.playing;
    playPauseBtn.setAttribute('aria-pressed', String(!state.playing));
    playPauseBtn.setAttribute('aria-label', state.playing ? 'Pause animation' : 'Play animation');
    playLabel.textContent = state.playing ? 'Pause' : 'Play';
    playIcon.innerHTML = state.playing
      ? '<path d="M8 5v14l11-7z"/>'
      : '<path d="M7 5h4v14H7zM13 5h4v14h-4z"/>';
    updateStateText();
  });

  document.getElementById('resetViewBtn').addEventListener('click', () => {
    if (state.tutorialOpen) closeTutorial();
    setActiveSeg(systemTypeGroup, state.systemType);
    startCameraTween(DEFAULT_VIEW.position, DEFAULT_VIEW.target);
  });

  tutorialBtn.addEventListener('click', () => { openTutorial(); });
  document.getElementById('tutorialClose').addEventListener('click', closeTutorial);
  tutorialNextBtn.addEventListener('click', tutorialNext);
  tutorialBackBtn.addEventListener('click', tutorialBack);
  document.addEventListener('keydown', (e) => {
    if (!state.tutorialOpen) return;
    if (e.key === 'Escape') closeTutorial();
    else if (e.key === 'ArrowRight') tutorialNext();
    else if (e.key === 'ArrowLeft') tutorialBack();
  });

  document.getElementById('labelsToggle').addEventListener('change', (e) => {
    state.labelsOn = e.target.checked;
    updateLabelVisibility();
  });

  const menuToggle = document.getElementById('menuToggle');
  const primaryControls = document.getElementById('primaryControls');
  menuToggle.addEventListener('click', () => {
    const open = primaryControls.classList.toggle('open');
    menuToggle.setAttribute('aria-expanded', String(open));
  });

  const hudEl = document.getElementById('hud');

  // ============================== Resize ==============================
  const viewportEl = document.getElementById('viewport');
  function handleResize(){
    const rect = viewportEl.getBoundingClientRect();
    const w = Math.max(1, Math.floor(rect.width));
    const h = Math.max(1, Math.floor(rect.height));
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
    if (composer) composer.setSize(w, h);
  }
  window.addEventListener('resize', handleResize);

  const reducedMotionMQ = window.matchMedia('(prefers-reduced-motion: reduce)');
  const onReducedMotionChange = (e) => { state.reducedMotion = e.matches; };
  if (reducedMotionMQ.addEventListener) reducedMotionMQ.addEventListener('change', onReducedMotionChange);

  // ============================== Per-frame updates ==============================
  function updateFansAndCompressors(dt, elapsed){
    const speedScale = flowSpeedScale();
    splitIndoor.fan.spin.rotation.y += 6.4 * speedScale * dt;
    splitOutdoor.fan.spin.rotation.y += 4.0 * speedScale * dt;
    monoCabinet.indoorFan.spin.rotation.y += 6.4 * speedScale * dt;
    monoCabinet.outdoorFan.spin.rotation.y += 4.4 * speedScale * dt;

    const pulse = 1 + Math.sin(elapsed*7.2)*0.016*speedScale;
    splitOutdoor.compressor.group.scale.setScalar(pulse);
    monoCabinet.compressor.group.scale.setScalar(pulse);

    const valveAngle = lerp(angleForMode(modeAnim.from), angleForMode(modeAnim.to), modeE());
    splitOutdoor.valve.slider.rotation.y = valveAngle;
    monoCabinet.valve.slider.rotation.y = valveAngle;
    const valveGlow = Math.sin(clamp(modeAnim.t,0,1)*Math.PI);
    splitOutdoor.valve.slider.material.emissive.setRGB(valveGlow*0.9, valveGlow*0.55, 0.08);
    monoCabinet.valve.slider.material.emissive.setRGB(valveGlow*0.9, valveGlow*0.55, 0.08);
  }

  function updateRefrigerantAndCoils(dt){
    const e = modeE();
    const speedScale = flowSpeedScale();
    const gasDirFor = (mode) => mode === 'cooling' ? 1 : -1;
    const liquidDirFor = (mode) => mode === 'cooling' ? -1 : 1;
    const gasDirNow = modeAnim.t < 0.5 ? gasDirFor(modeAnim.from) : gasDirFor(modeAnim.to);
    const liquidDirNow = modeAnim.t < 0.5 ? liquidDirFor(modeAnim.from) : liquidDirFor(modeAnim.to);

    const gasColorNow = scratch1.copy(modeAnim.from === 'cooling' ? GAS_COOL_COLOR : GAS_HOT_COLOR)
      .lerp(modeAnim.to === 'cooling' ? GAS_COOL_COLOR : GAS_HOT_COLOR, e);

    if (splitGroup.visible){
      refrigerantGasSplit.direction = gasDirNow; refrigerantGasSplit.speed = 0.16*speedScale;
      refrigerantLiquidSplit.direction = liquidDirNow; refrigerantLiquidSplit.speed = 0.13*speedScale;
      refrigerantGasSplit.update(dt, () => gasColorNow);
      refrigerantLiquidSplit.update(dt, () => LIQUID_COLOR);

      splitIndoor.coil.finMat.emissive.copy(roleColorObj(indoorRole(modeAnim.from))).lerp(roleColorObj(indoorRole(modeAnim.to)), e);
      splitIndoor.coil.tubeMat.emissive.copy(splitIndoor.coil.finMat.emissive);
      splitOutdoor.coil.finMat.emissive.copy(roleColorObj(outdoorRole(modeAnim.from))).lerp(roleColorObj(outdoorRole(modeAnim.to)), e);
      splitOutdoor.coil.tubeMat.emissive.copy(splitOutdoor.coil.finMat.emissive);
    }
    if (monoGroup.visible){
      refrigerantGasMono.direction = gasDirNow; refrigerantGasMono.speed = 0.4*speedScale;
      refrigerantLiquidMono.direction = liquidDirNow; refrigerantLiquidMono.speed = 0.34*speedScale;
      refrigerantGasMono.update(dt, () => gasColorNow);
      refrigerantLiquidMono.update(dt, () => LIQUID_COLOR);

      monoCabinet.indoorCoil.finMat.emissive.copy(roleColorObj(indoorRole(modeAnim.from))).lerp(roleColorObj(indoorRole(modeAnim.to)), e);
      monoCabinet.indoorCoil.tubeMat.emissive.copy(monoCabinet.indoorCoil.finMat.emissive);
      monoCabinet.outdoorCoil.finMat.emissive.copy(roleColorObj(outdoorRole(modeAnim.from))).lerp(roleColorObj(outdoorRole(modeAnim.to)), e);
      monoCabinet.outdoorCoil.tubeMat.emissive.copy(monoCabinet.outdoorCoil.finMat.emissive);
    }
  }

  function updateAirParticles(dt){
    const e = modeE();
    const speedScale = flowSpeedScale();
    const tintNow = scratch2.copy(modeAnim.from === 'cooling' ? AIR_COOL_TINT : AIR_WARM_TINT)
      .lerp(modeAnim.to === 'cooling' ? AIR_COOL_TINT : AIR_WARM_TINT, e);
    const outTintNow = scratch3.copy(modeAnim.from === 'cooling' ? AIR_WARM_TINT : AIR_COOL_TINT)
      .lerp(modeAnim.to === 'cooling' ? AIR_WARM_TINT : AIR_COOL_TINT, e);

    if (splitGroup.visible){
      roomAirSplit.speed = 0.11*speedScale;
      outdoorAirSplit.speed = 0.13*speedScale;
      roomAirSplit.update(dt, (t) => scratch4.copy(AIR_BASE).lerp(tintNow, mixFactor(t)));
      outdoorAirSplit.update(dt, (t) => scratch4.copy(AIR_OUT_BASE).lerp(outTintNow, mixFactor(t)));
    }
    if (monoGroup.visible){
      roomAirMono.speed = 0.11*speedScale;
      outdoorAirManoIn.speed = 0.26*speedScale;
      outdoorAirManoOut.speed = 0.26*speedScale;
      roomAirMono.update(dt, (t) => scratch4.copy(AIR_BASE).lerp(tintNow, mixFactor(t)));
      outdoorAirManoIn.update(dt, () => AIR_OUT_BASE);
      outdoorAirManoOut.update(dt, (t) => scratch4.copy(AIR_OUT_BASE).lerp(outTintNow, mixFactor(t)));
    }
  }

  function updateHeatAndDrips(dt){
    const indoorEvap = indoorRole(state.mode) === 'evaporator';
    const outdoorEvap = outdoorRole(state.mode) === 'evaporator';
    const activeSplit = splitGroup.visible;
    const activeMono = monoGroup.visible;

    heatSplitIndoor.update(dt, indoorEvap, activeSplit);
    heatSplitOutdoor.update(dt, outdoorEvap, activeSplit);
    heatMonoIndoor.update(dt, indoorEvap, activeMono);
    heatMonoOutdoor.update(dt, outdoorEvap, activeMono);

    dripSplit.update(dt, activeSplit && state.mode === 'cooling');
    dripMono.update(dt, activeMono && state.mode === 'cooling');
  }

  // ============================== Boot ==============================
  labelDefs = buildLabelDefs();
  rebuildLabels();
  updateLabelVisibility();
  updateStateText();
  handleResize();

  const clock = new THREE.Clock();
  function animate(){
    requestAnimationFrame(animate);
    const dt = Math.min(clock.getDelta(), 0.05);
    const elapsed = clock.getElapsedTime();

    controls.update();

    if (camAnim.active){
      camAnim.t += dt / camAnim.duration;
      const e = easeInOutCubic(clamp(camAnim.t, 0, 1));
      camera.position.lerpVectors(camAnim.fromPos, camAnim.toPos, e);
      controls.target.lerpVectors(camAnim.fromTarget, camAnim.toTarget, e);
      if (camAnim.t >= 1){ camAnim.active = false; controls.enabled = true; }
    }

    if (state.playing){
      if (modeAnim.t < 1) modeAnim.t = Math.min(1, modeAnim.t + dt/modeAnim.duration);

      state.indoorTemp += (state.indoorTarget - state.indoorTemp) * Math.min(1, dt*0.4);
      state.outdoorTemp += (state.outdoorTarget - state.outdoorTemp) * Math.min(1, dt*0.4);
      document.getElementById('indoorTemp').textContent = `${state.indoorTemp.toFixed(1)}°C`;
      document.getElementById('outdoorTemp').textContent = `${state.outdoorTemp.toFixed(1)}°C`;

      updateFansAndCompressors(dt, elapsed);
      updateRefrigerantAndCoils(dt);
      updateAirParticles(dt);
      updateHeatAndDrips(dt);
    }

    if (highlightSprite.visible){
      const pulse = 0.75 + Math.sin(elapsed*2.4)*0.22;
      highlightSprite.material.opacity = 0.4 + pulse*0.25;
    }

    camera.updateMatrixWorld();
    updateLabels();

    if (composer) composer.render(); else renderer.render(scene, camera);
  }
  animate();
}
