import { chromium } from 'playwright';

const browser = await chromium.launch({
  channel: 'chrome',
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', err => errors.push(err.message));
page.on('console', msg => { if (msg.type() === 'error' && !msg.text().includes('404')) errors.push('[console.error] ' + msg.text()); });

await page.goto('http://localhost:8934/index.html', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(1500);

// Monoblock
await page.click('#systemTypeGroup [data-value="monoblock"]');
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/shot_monoblock.png' });

// Heating
await page.click('#modeGroup [data-value="heating"]');
await page.waitForTimeout(1800);
await page.screenshot({ path: '/tmp/shot_monoblock_heating.png' });

// Back to split, cooling
await page.click('#systemTypeGroup [data-value="split"]');
await page.waitForTimeout(1500);
await page.click('#modeGroup [data-value="cooling"]');
await page.waitForTimeout(1000);

// Tutorial flow
await page.click('#tutorialBtn');
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/shot_tutorial_1.png' });
for (let i=0;i<7;i++){
  await page.click('#tutorialNext');
  await page.waitForTimeout(1300);
}
await page.screenshot({ path: '/tmp/shot_tutorial_last.png' });
await page.click('#tutorialClose');
await page.waitForTimeout(300);

// Pause
await page.click('#playPauseBtn');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/shot_paused.png' });
await page.click('#playPauseBtn');

// Reset view
await page.click('#resetViewBtn');
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/shot_reset.png' });

// Mobile viewport
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/shot_mobile.png' });
await page.click('#menuToggle');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/shot_mobile_menu.png' });

console.log('--- ERRORS ---');
errors.forEach(e => console.log(e));
console.log('DONE');

await browser.close();
EOF
