function startCameraTween(pos, target){
  // Paced by real wall-clock time (not per-frame delta) so it always finishes
  // in ~1s of actual time and can't be thrown into slow motion by a slow
  // frame rate or by clamped simulation deltas.
  camAnim.active = true;
  camAnim.startTime = performance.now();
  camAnim.duration = state.reducedMotion ? 60 : 1050;
  camAnim.fromPos.copy(camera.position);
  camAnim.fromTarget.copy(controls.target);
  camAnim.toPos.copy(pos);
  camAnim.toTarget.copy(target);
  controls.enabled = false;
}

