import { chromium } from 'playwright';
const browser = await chromium.launch({
  channel: 'chrome', headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type()==='error' && !m.text().includes('404')) errors.push('[console] '+m.text()); });

await page.goto('http://localhost:8934/index.html', { waitUntil: 'load' });
await page.waitForTimeout(1000);

async function runTutorial(prefix){
  await page.click('#tutorialBtn');
  await page.waitForTimeout(1400);
  await page.screenshot({ path: `/tmp/${prefix}_step1.png` });
  for (let i=2;i<=8;i++){
    await page.click('#tutorialNext');
    await page.waitForTimeout(1400);
    await page.screenshot({ path: `/tmp/${prefix}_step${i}.png` });
  }
  await page.click('#tutorialClose');
  await page.waitForTimeout(300);
}

await runTutorial('split');
await page.click('#systemTypeGroup [data-value="monoblock"]');
await page.waitForTimeout(1400);
await runTutorial('mono');

console.log('ERRORS:', errors.length);
errors.forEach(e=>console.log(e));
await browser.close();
EOF
